        ],
        "rationale": "Paragraph 10 expressly assigns ultimate responsibility, and footnote 1 confirms that outsourcing does not transfer it. This supports allocation of responsibility, not a finding of adequate supervision or sound operations.",
        "status": "SUPPORTED"
      }
    },
    {
      "authority": {
        "dependency_ids": [],
        "rationale": "Paragraph 14 and footnote 5 support assessment of the expressly stipulated reading without additional external authority. The packet does not conclusively resolve the alternative interpretation of footnote 5.",
        "status": "NONE_DECLARED"
      },
      "candidate_id": "deferred.9d6ef75f1b5f4ae94e41f5d5",
      "claim_id": "claim.b8bfeece7669b37ae5c67d5f",
      "executable_correspondence": {
        "rationale": "Within provider_in_scope, the result is demonstration_requested, preserving activation under the question's express request-conditioned reading. Demonstration content, performance and SFC satisfaction are not additional activation conditions. Preservation is limited to this typed trigger question and does not adjudicate the rival footnote reading.",
        "representation_quotes": [
          "exec2.61bed931eaf08ffba000a3bbd70484a683d98f886f5e209c4ca05eb1fff5c8ea",
